p='/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-hermesagentlearner-1790682248/attempts/39485cff12924707af44e08ccf1c69c3/system/state/hermes/state.db'; c=sqlite3.connect(p);s='2802560a-133c-4248-a4b9-05349291a97e'
def parse(content):
 I=[];O=[];sec=''
 for ln in content.splitlines():
  if re.match(r'Demo pair \d+ input',ln):sec='i';continue
  if re.match(r'Demo pair \d+ output',ln):sec='o';continue
  if ln.startswith('Same instance'):sec='';
  if sec and re.fullmatch(r'[0-9 ]+',ln.strip()): (I if sec=='i' else O).append(list(map(int,ln.split())))
 return I,O
for mid,txt in c.execute("select id,content from messages where session_id=? and role='user'",(s,)):
 if not txt or 'Demo pair' not in txt:continue
 I,O=parse(txt); h,w=len(O),len(O[0]); coords=[(r,c) for r,row in enumerate(I) for c,x in enumerate(row) if x==8];r0=min(r for r,c in coords);c0=min(c for r,c in coords)
 # Compare exact windows of input, except 8 positions; list best match
 cand=[]
 for a in range(30-h+1):
  for b in range(30-w+1):
   d=sum(I[a+i][b+j]!=O[i][j] for i in range(h) for j in range(w))
   cand.append((d,a,b))
 print('\n',mid,'hole',r0,c0,h,w,'best windows',sorted(cand)[:8])
 # source row sequence: for each target output row, best row in I over all start cols; compare starting column c0
 for i,row in enumerate(O):
  candrow=[]
  for rr in range(30):
   for cc in range(30-w+1):
    d=sum(I[rr][cc+j]!=row[j] for j in range(w))
    candrow.append((d,rr,cc))
